solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <vector>

class StackSim
{
public:
    StackSim(std::uint64_t top, std::uint64_t size) : top{ top }, bottom{ top - size }, pointer{ top } {}

    std::optional<std::uint64_t> call(std::uint64_t localBytes)
    {
        const std::uint64_t frame{ (8 + localBytes + 15) / 16 * 16 };
        if (pointer - bottom < frame) return std::nullopt;
        pointer -= frame;
        frames.push_back(frame);
        if (top - pointer > highest) highest = top - pointer;
        return pointer;
    }

    bool ret()
    {
        if (frames.empty()) return false;
        pointer += frames.back();
        frames.pop_back();
        return true;
    }

    std::uint64_t sp() const { return pointer; }
    int depth() const { return static_cast<int>(frames.size()); }
    std::uint64_t peak() const { return highest; }

private:
    std::uint64_t top, bottom, pointer;
    std::uint64_t highest{ 0 };
    std::vector<std::uint64_t> frames;
};

int deepestRecursion(std::uint64_t stackSize, std::uint64_t localBytes)
{
    const std::uint64_t frame{ (8 + localBytes + 15) / 16 * 16 };
    return static_cast<int>(stackSize / frame);
}

unitTests:
TEST("frames grow downwards") {
    StackSim s{ 0x10000, 0x1000 };
    CHECK_EQ(s.sp(), 0x10000ull);
    CHECK_EQ(s.call(24).value_or(0), 0xFFE0ull);
    CHECK_EQ(s.call(0).value_or(0), 0xFFD0ull);
    CHECK_EQ(s.call(100).value_or(0), 0xFF60ull);
    CHECK_EQ(s.depth(), 3);
}
TEST("returning moves back up") {
    StackSim s{ 0x10000, 0x1000 };
    s.call(24); s.call(100);
    CHECK(s.ret());
    CHECK_EQ(s.sp(), 0xFFE0ull);
    CHECK(s.ret());
    CHECK_EQ(s.sp(), 0x10000ull);
    CHECK(!s.ret());
    CHECK_EQ(s.depth(), 0);
}
TEST("overflow is refused") {
    StackSim s{ 0x2000, 0x100 };
    int calls{ 0 };
    while (s.call(56)) ++calls;
    CHECK_EQ(calls, 4);
    CHECK_EQ(s.sp(), 0x1F00ull);
    CHECK(!s.call(0).has_value());
    CHECK_EQ(s.depth(), 4);
}
TEST("peak usage") {
    StackSim s{ 0x10000, 0x1000 };
    s.call(8); s.call(8); s.ret(); s.ret(); s.call(200);
    CHECK_EQ(s.peak(), 208ull);
    s.ret(); s.call(8);
    CHECK_EQ(s.peak(), 208ull);
}
TEST("how deep can recursion go") {
    CHECK_EQ(deepestRecursion(1024 * 1024, 40), 21845);
    CHECK_EQ(deepestRecursion(1024 * 1024, 2'000'000), 0);
    CHECK_EQ(deepestRecursion(256, 8), 16);
}

